#include <string>
using namespace std;

vector<string> letterCombinations(string digits) {
    if(digits.empty()) return {};
    vector<string> phone = {"abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    vector<string> result = {""};

    for (char d : digits) {
        vector<string> temp;
        for (const string &s : result) {
            for (char c : phone[d - '2']) {
                temp.push_back(s + c);
            }
        }
        result.swap(temp);
    }
    return result;
}

