function letterCombinations(digits) {
    if (digits.length === 0) return [];

    let phone = ["abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"];
    let result = [""];

    for (let i = 0; i < digits.length; i++) {
        let digit = digits[i];
        let temp = [];

        for (let s of result) {
            for (let c of phone[digit - 2]) {
                temp.push(s + c);
            }
        }

        result = temp;
    }

    return result;
}

