```python
from collections import deque

def letterCombinations(digits):
    output = deque()
    if not digits:
        return list(output)

    phone = ["abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"]
    output.append("")

    for d in digits:
        while len(output[0]) == digits.index(d):
            perm = output.popleft()
            for c in phone[int(d) - 2]:
                output.append(perm + c)

    return list(output)
```

