java_code:
import java.util.ArrayList;
import java.util.List;

public List<List<Integer>> combinationSum(int[] candidates, int target) {
    List<List<Integer>> result = new ArrayList<>();
    findCombinations(candidates, target, 0, new ArrayList<>(), result);
    return result;
}

private void findCombinations(int[] candidates, int target, int startIndex, List<Integer> current, List<List<Integer>> result) {
    if (target == 0) {
        result.add(new ArrayList<>(current));
        return;
    }
    if (startIndex == candidates.length || target < 0) {
        return;
    }

    findCombinations(candidates, target, startIndex + 1, current, result);

    current.add(candidates[startIndex]);
    findCombinations(candidates, target - candidates[startIndex], startIndex, current, result);
    current.remove(current.size() - 1);
}

cpp_code:
#include <vector>

void findCombinations(std::vector<int>& candidates, int target, int startIndex, std::vector<int>& current, std::vector<std::vector<int>>& result) {
    if (target == 0) {
        result.push_back(current);
        return;
    }
    if (startIndex == candidates.size() || target < 0) {
        return;
    }

    findCombinations(candidates, target, startIndex + 1, current, result);

    current.push_back(candidates[startIndex]);
    findCombinations(candidates, target - candidates[startIndex], startIndex, current, result);
    current.pop_back();
}

std::vector<std::vector<int>> combinationSum(std::vector<int>& candidates, int target) {
    std::vector<int> current;
    std::vector<std::vector<int>> result;
    findCombinations(candidates, target, 0, current, result);
    return result;
}

python_code:
def combinationSum(candidates, target):
    def findCombinations(startIndex, remaining):
        if remaining == 0:
            return [[]]
        if startIndex == len(candidates) or remaining < 0:
            return []

        result = []
        result.extend(findCombinations(startIndex + 1, remaining))
        result.extend([x + [candidates[startIndex]] for x in findCombinations(startIndex, remaining - candidates[startIndex])])

        return result

    return findCombinations(0, target)

