java_code:
import java.util.ArrayList;

public int totalNQueens(int n) {
    ArrayList<Integer> cols = new ArrayList<>();
    return backtrack(n, cols);
}

public int backtrack(int n, ArrayList<Integer> cols) {
    if (cols.size() == n) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < n; i++) {
        if (isSafe(cols, i)) {
            cols.add(i);
            count += backtrack(n, cols);
            cols.remove(cols.size() - 1);
        }
    }
    return count;
}

public boolean isSafe(ArrayList<Integer> cols, int row) {
    int col = cols.size();
    for (int i = 0; i < cols.size(); i++) {
        if (cols.get(i) == row || Math.abs(i - col) == Math.abs(cols.get(i) - row)) {
            return false;
        }
    }
    return true;
}

cpp_code:
#include <vector>
using namespace std;

bool isSafe(vector<int> &cols, int row) {
    int col = cols.size();
    for (int i = 0; i < cols.size(); i++) {
        if (cols[i] == row || abs(i - col) == abs(cols[i] - row)) {
            return false;
        }
    }
    return true;
}

void backtrack(int n, vector<int> &cols, int &count) {
    if (cols.size() == n) {
        count++;
        return;
    }

    for (int i = 0; i < n; i++) {
        if (isSafe(cols, i)) {
            cols.push_back(i);
            backtrack(n, cols, count);
            cols.pop_back();
        }
    }
}

int totalNQueens(int n) {
    vector<int> cols;
    int count = 0;
    backtrack(n, cols, count);
    return count;
}

