std::string addBinary(std::string a, std::string b) {
    std::string result = "";
    int i = a.size() - 1, j = b.size() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        if (i >= 0) carry += a[i--] - '0';
        if (j >= 0) carry += b[j--] - '0';
        result = char(carry % 2 + '0') + result;
        carry /= 2;
    }
    return result;
}

