from collections import deque

def simplifyPath(path):
    parts = path.split("/")
    stack = deque()

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
        else:
            stack.append(part)

    canonicalPath = ""
    for piece in stack:
        canonicalPath += "/" + piece

    return "/" if not stack else canonicalPath
