java_code:
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;

public int ladderLength(String beginWord, String endWord, List<String> wordList) {
    Set<String> dict = new HashSet<>(wordList);
    if (!dict.contains(endWord)) return 0;

    Queue<String> q = new LinkedList<>();
    q.offer(beginWord);
    int steps = 1;

    while (!q.isEmpty()) {
        int size = q.size();
        for (int i = 0; i < size; ++i) {
            String currentWord = q.poll();
            if (currentWord.equals(endWord)) return steps;

            char[] charArray = currentWord.toCharArray();
            for (int j = 0; j < charArray.length; ++j) {
                char originalChar = charArray[j];
                for (int k = 0; k < 26; ++k) {
                    charArray[j] = (char) ('a' + k);
                    String newWord = new String(charArray);
                    if (dict.remove(newWord)) {
                        q.offer(newWord);
                    }
                }
                charArray[j] = originalChar;
            }
        }
        ++steps;
    }
    return 0;
}

cpp_code:
#include <string>
#include <vector>
#include <queue>
#include <unordered_set>

int ladderLength(std::string beginWord, std::string endWord, std::vector<std::string>& wordList) {
    std::unordered_set<std::string> dict(wordList.begin(), wordList.end());
    if (!dict.count(endWord)) return 0;

    std::queue<std::string> q;
    q.push(beginWord);
    int steps = 1;

    while (!q.empty()) {
        int size = q.size();
        for (int i = 0; i < size; ++i) {
            std::string currentWord = q.front();
            q.pop();
            if (currentWord == endWord) return steps;

            for (char& c : currentWord) {
                char originalChar = c;
                for (int j = 0; j < 26; ++j) {
                    c = 'a' + j;
                    if (dict.count(currentWord)) {
                        q.push(currentWord);
                        dict.erase(currentWord);
                    }
                }
                c = originalChar;
            }
        }
        ++steps;
    }
    return 0;
}

javascript_code:
function ladderLength(beginWord, endWord, wordList) {
    const wordSet = new Set(wordList);
    if (!wordSet.has(endWord)) return 0;

    const q = [beginWord];
    let steps = 1;

    while (q.length > 0) {
        const size = q.length;
        const currentLevel = new Set();

        for (let i = 0; i < size; ++i) {
            const currentWord = q.shift();
            if (currentWord === endWord) return steps;

            const wordChars = currentWord.split('');
            for (let j = 0; j < wordChars.length; ++j) {
                const originalChar = wordChars[j];
                for (let k = 0; k < 26; ++k) {
                    wordChars[j] = String.fromCharCode('a'.charCodeAt(0) + k);
                    const newWord = wordChars.join('');
                    if (wordSet.has(newWord)) {
                        q.push(newWord);
                        currentLevel.add(newWord);
                    }
                }
                wordChars[j] = originalChar;
            }
        }
        steps++;
        for (const word of currentLevel) {
            wordSet.delete(word);
        }
    }
    return 0;
}

