    if endWord not in wordSet:
        return 0

    q = deque([beginWord])
    steps = 1

    while q:
        size = len(q)
        currentLevel = set()

        for _ in range(size):
            currentWord = q.popleft()
            if currentWord == endWord:
                return steps

            wordChars = list(currentWord)
            for j in range(len(wordChars)):
