                for k in range(26):
                    wordChars[j] = chr(ord('a') + k)
                    newWord = ''.join(wordChars)
                    if newWord in wordSet:
                        q.append(newWord)
                        currentLevel.add(newWord)
                wordChars[j] = originalChar

        steps += 1
        for word in currentLevel:
            wordSet.remove(word)

    return 0

