java_code:
public int longestConsecutive(int[] nums) {
    Set<Integer> elements = new HashSet<>();
    for (int num : nums) {
        elements.add(num);
    }

    int longestSeq = 0;

    for (int num : nums) {
        if (!elements.contains(num - 1)) {
            int currentNum = num;
            int currentSeq = 1;

            while (elements.contains(currentNum + 1)) {
                currentNum++;
                currentSeq++;
            }

            longestSeq = Math.max(longestSeq, currentSeq);
        }
    }
    return longestSeq;
}

cpp_code:
int longestConsecutive(vector<int>& nums) {
    unordered_set<int> elements(nums.begin(), nums.end());
    int longestSeq = 0;

    for (int num : nums) {
        if (elements.find(num - 1) == elements.end()) {
            int currentNum = num;
            int currentSeq = 1;

            while (elements.find(currentNum + 1) != elements.end()) {
                currentNum += 1;
                currentSeq += 1;
            }

            longestSeq = max(longestSeq, currentSeq);
        }
    }
    return longestSeq;
}

