java_code:
public int sumNumbers(TreeNode root) {
    return sumNumbersHelper(root, 0);
}

private int sumNumbersHelper(TreeNode root, int cur) {
    if (root == null) return 0;
    cur = cur * 10 + root.val;
    if (root.left == null && root.right == null) return cur;
    return sumNumbersHelper(root.left, cur) + sumNumbersHelper(root.right, cur);
}

cpp_code:
int sumNumbers(TreeNode* root, int cur = 0) {
    if (!root) return 0;
    cur = cur * 10 + root->val;
    if (!root->left && !root->right) return cur;
    return sumNumbers(root->left, cur) + sumNumbers(root->right, cur);
}

