java_code:
public int canCompleteCircuit(int[] gas, int[] cost) {
    int totalGas = 0, totalCost = 0, start = 0, gasTank = 0;
    for (int i = 0; i < gas.length; i++) {
        totalGas += gas[i];
        totalCost += cost[i];
        gasTank += gas[i] - cost[i];
        if (gasTank < 0) {
            start = i + 1;
            gasTank = 0;
        }
    }
    return (totalGas < totalCost) ? -1 : start;
}

