int can_complete_circuit(vector<int>& gas, vector<int>& cost) {
    int total_gas = 0, total_cost = 0, start = 0, gas_tank = 0;
    for (int i = 0; i < gas.size(); ++i) {
        total_gas += gas[i];
        total_cost += cost[i];
        gas_tank += gas[i] - cost[i];
        if (gas_tank < 0) {
            start = i + 1;
            gas_tank = 0;
        }
    }
    return (total_gas < total_cost) ? -1 : start;
}

