cpp_code:
#include <string>
#include <sstream>
#include <vector>
#include <algorithm>

std::string reverseWords(std::string s) {
    std::stringstream ss(s);
    std::vector<std::string> words;
    std::string temp;

    while (ss >> temp) {
        words.push_back(temp);
    }

    std::reverse(words.begin(), words.end());

    std::string result;
    for (size_t i = 0; i < words.size(); ++i) {
        result += words[i] + (i < words.size() - 1 ? " " : "");
    }

    return result;
}

