    if (n == 0) return result;

    int start = nums[0];
    for (int i = 1; i < n; ++i) {
        if (nums[i] > nums[i-1] + 1) {
            if (start == nums[i-1])
                result.push_back(std::to_string(start));
            else
                result.push_back(std::to_string(start) + "->" + std::to_string(nums[i-1]));
            start = nums[i];
        }
    }

    if (start == nums[n-1])
        result.push_back(std::to_string(start));
    else
        result.push_back(std::to_string(start) + "->" + std::to_string(nums[n-1]));

    return result;
}

