bool isAnagram(std::string s, std::string t) {
    if(s.size() != t.size())
        return false;

    std::unordered_map<char, int> counts;
    for(char c : s)
        counts[c]++;

    for(char c : t) {
        if(counts[c] == 0)
            return false;
        counts[c]--;
    }

    return true;
}

