java_code:
public List<int[]> kSmallestPairs(int[] nums1, int[] nums2, int k) {
    PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> (a[0] + a[1]) - (b[0] + b[1]));
    List<int[]> result = new ArrayList<>();

    if (nums1.length == 0 || nums2.length == 0 || k == 0) {
        return result;
    }

    for (int i = 0; i < nums1.length && i < k; i++) {
        minHeap.offer(new int[]{nums1[i], nums2[0], 0});
    }

    while (k-- > 0 && !minHeap.isEmpty()) {
        int[] curr = minHeap.poll();
        result.add(new int[]{curr[0], curr[1]});
        if (curr[2] == nums2.length - 1) {
            continue;
        }
        minHeap.offer(new int[]{curr[0], nums2[curr[2] + 1], curr[2] + 1});
    }

    return result;
}

cpp_code:
vector<vector<int>> kSmallestPairs(vector<int>& nums1, vector<int>& nums2, int k) {
    auto comp = [&nums1, &nums2](pair<int, int> a, pair<int, int> b) {
        return nums1[a.first] + nums2[a.second] > nums1[b.first] + nums2[b.second];
    };
    priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(comp)> min_heap(comp);
    vector<vector<int>> result;

    if (nums1.empty() || nums2.empty()) return result;

    for (int i = 0; i < nums1.size(); ++i) {
        min_heap.emplace(i, 0);
    }

    while (k-- && !min_heap.empty()) {
        auto curr = min_heap.top();
        min_heap.pop();
        result.push_back({nums1[curr.first], nums2[curr.second]});
        if (curr.second + 1 < nums2.size()) {
            min_heap.emplace(curr.first, curr.second + 1);
        }
    }
    return result;
}

