```python
import heapq

class PriorityQueue:
    def __init__(self, k, key):
        self.k = k
        self.key = key
        self.data = []

    def offer(self, item):
        if len(self.data) < self.k:
            heapq.heappush(self.data, (self.key(item), item))
        else:
            heapq.heappushpop(self.data, (self.key(item), item))

    def poll(self):
        return heapq.heappop(self.data)[1]

    def isEmpty(self):
        return len(self.data) == 0

def kSmallestPairs(nums1, nums2, k):
    minHeap = PriorityQueue(k, lambda x: x[0] + x[1])
    result = []

    if len(nums1) == 0 or len(nums2) == 0 or k == 0:
        return result

    for i in range(min(len(nums1), k)):
        minHeap.offer([nums1[i], nums2[0], 0])

    while k > 0 and not minHeap.isEmpty():
        curr = minHeap.poll()
        result.append([curr[0], curr[1]])
        if curr[2] == len(nums2) - 1:
            continue
        minHeap.offer([curr[0], nums2[curr[2] + 1], curr[2] + 1])
        k -= 1

    return result
```

