java_code:
import java.util.*;

class Solution {
    public int reachableNodes(int[][] edges, int maxMoves, int n) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            int u = edge[0], v = edge[1], cnt = edge[2];
            graph.get(u).add(new int[]{v, cnt + 1});
            graph.get(v).add(new int[]{u, cnt + 1});
        }

        Set<Integer> visited = new HashSet<>();
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        pq.offer(new int[]{maxMoves, 0});

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int moves_left = top[0];
            int node = top[1];

            if (visited.contains(node)) continue;
            visited.add(node);

            for (int[] neighbor : graph.get(node)) {
                int next_node = neighbor[0];
                int moves_needed = neighbor[1];
                int moves_left_after = moves_left - moves_needed;

                if (!visited.contains(next_node) && moves_left_after > 0) {
                    pq.offer(new int[]{moves_left_after, next_node});
                }
            }
        }

        return visited.size();
    }
}

cpp_code:
#include <vector>
#include <unordered_set>
#include <queue>

using namespace std;

int reachableNodes(vector<vector<int>>& edges, int maxMoves, int n) {
    vector<vector<pair<int, int>>> graph(n);
    for (const auto& edge : edges) {
        int u = edge[0], v = edge[1], cnt = edge[2];
        graph[u].emplace_back(v, cnt + 1);
        graph[v].emplace_back(u, cnt + 1);
    }

    unordered_set<int> visited;
    priority_queue<pair<int, int>> pq;
    pq.emplace(maxMoves, 0);

    while (!pq.empty()) {
        int moves_left = pq.top().first;
        int node = pq.top().second;
        pq.pop();

        if (visited.count(node)) continue;
        visited.insert(node);

        for (const auto& neighbor : graph[node]) {
            int next_node = neighbor.first;
            int moves_needed = neighbor.second;
            int moves_left_after = moves_left - moves_needed;

            if (!visited.count(next_node) && moves_left_after > 0) {
                pq.emplace(moves_left_after, next_node);
            }
        }
    }

    return visited.size();
}

python_code:
from heapq import heappush, heappop

def reachableNodes(edges, maxMoves, n):
    graph = [[] for _ in range(n)]
    for u, v, cnt in edges:
        graph[u].append((v, cnt + 1))
        graph[v].append((u, cnt + 1))

    visited = set()
    pq = [(-maxMoves, 0)]

    while pq:
        moves_left, node = heappop(pq)

        if node in visited:
            continue
        visited.add(node)

        for next_node, moves_needed in graph[node]:
            moves_left_after = moves_left - moves_needed
            if next_node not in visited and moves_left_after > 0:
                heappush(pq, (moves_left_after, next_node))

    return len(visited)

