import heapq

def reachableNodes(edges, maxMoves, n):
    graph = [[] for _ in range(n)]
    for edge in edges:
        u, v, cnt = edge
        graph[u].append((v, cnt + 1))
        graph[v].append((u, cnt + 1))

    visited = set()
    pq = [(maxMoves, 0)]

    while pq:
        moves_left, node = heapq.heappop(pq)

        if node in visited:
            continue
        visited.add(node)

        for neighbor in graph[node]:
            next_node, moves_needed = neighbor
            moves_left_after = moves_left - moves_needed

            if next_node not in visited and moves_left_after > 0:
                heapq.heappush(pq, (moves_left_after, next_node))

    return len(visited)
